const localAvatar=(name,cls)=>{const p=localProfilePhoto();return p?'<img class="'+(cls||'person-photo')+'" src="'+esc(p)+'">':'<div class="'+(cls||'person-photo')+'">'+esc(initials(name))+'</div>'};
