async function load(){const r=await supabase.auth.getUser();user=r.data.user;if(!user){auth('login');return}const p=await supabase.from('profiles').select('*').eq('id',user.id).maybeSingle();profile=p.data;const a=await supabase.from('leader_assignments').select('*').eq('user_id',user.id).eq('active',true).maybeSingle();assignment=a.data;$('authView').classList.add('hidden');$('appView').classList.remove('hidden');$('avatarButton').innerHTML=profile?.profile_photo_path?'<img src="'+esc(photo(profile.profile_photo_path))+'" alt="">':esc(initials(profile?.full_name||user.email));$('adminNav').classList.toggle('hidden',profile?.role!=='admin');const inviteToken=new URLSearchParams(location.search).get('gc');if(inviteToken&&profile?.status==='approved'){const joined=await supabase.rpc('join_chat_by_token',{p_token:inviteToken});if(!joined.error){history.replaceState({},'',location.pathname);toast('Joined group successfully.')}else toast(joined.error.message)}await loadAnnouncements();await refreshNotificationBadge();page(location.hash==='#chat'?'chat':location.hash==='#announcements'?'announcements':'home')}
async function loadAnnouncements(){
  if(!profile||profile.status!=='approved'){announcements=[];return}
  await cleanupAnnouncementCache();
  const r=await supabase.from('announcements').select('*, announcement_images(id,storage_path,sort_order), announcement_links(id,url,sort_order), announcement_attachments(id,storage_path,file_name,mime_type,file_size,sort_order)').order('created_at',{ascending:false});
  if(r.error){
    const cached=await readCachedAnnouncements();
    if(cached){announcements=cached;return}
    return toast(r.error.message)
  }
  announcements=r.data||[];
  const paths=[];
  for(const a of announcements){
    for(const x of (a.announcement_images||[])){const z=await supabase.storage.from('campus-announcements').createSignedUrl(x.storage_path,86400);x.url=z.data?.signedUrl||null;if(x.url)paths.push(x.url)}
    for(const x of (a.announcement_attachments||[])){const z=await supabase.storage.from('campus-announcements').createSignedUrl(x.storage_path,86400);x.url=z.data?.signedUrl||null;if(x.url)paths.push(x.url)}
  }
  await cacheAnnouncementsData();
  if(cacheEnabled())await Promise.all(paths.map(cacheAnnouncementAsset));
}
function canEditAnnouncement(a){return !!user&&(profile?.role==='admin'||(a.author_id===user.id&&!!assignment?.can_announce))}
function card(a){
  const imgs=(a.announcement_images||[]).filter(x=>x.url).map(x=>'<img src="'+esc(x.url)+'" alt="Announcement image">').join('');
  const files=(a.announcement_attachments||[]).filter(x=>x.url).map(x=>'<a class="attachment" target="_blank" rel="noopener" href="'+esc(x.url)+'"><span class="file-icon">↗</span><span>'+esc(x.file_name||'File')+'<small>'+humanSize(x.file_size)+'</small></span></a>').join('');
  const links=(a.announcement_links||[]).map(x=>'<a class="attachment" target="_blank" rel="noopener" href="'+esc(x.url)+'"><span class="file-icon">↗</span><span>'+esc(x.url)+'</span></a>').join('');
  const edit=canEditAnnouncement(a)?'<div class="actions"><button class="ghost compact" onclick="editAnnouncement(\''+a.id+'\')">Edit announcement</button></div>':'';
  return '<article class="card announcement"><div class="announcement-head">'+avatar(null,a.author_page_name||a.author_name)+'<div><b>'+esc(a.author_page_name||a.author_name)+'</b><div class="meta">'+esc(a.author_title||'CampusOS publisher')+'</div></div></div><div class="announcement-body">'+esc(a.body)+'</div>'+(imgs?'<div class="announcement-images">'+imgs+'</div>':'')+(files||links?'<div class="attachment-list">'+files+links+'</div>':'')+edit+'</article>';
}
