async function openChat(id){activeChat=id;const g=chatRows.find(x=>x.id===id);if(!g)return;const room=$('chatRoom');const canDelete=g.owner_id===user.id||profile?.role==='admin';room.innerHTML='<header class="messenger-room-head">'+avatar(g.photo_path,g.name,'messenger-avatar')+'<div class="messenger-room-title"><b>'+esc(g.name)+'</b><small>Private group · CampusOS</small></div><div class="messenger-room-actions"><button class="icon-action" id="inviteGc" title="Add people">＋</button><button class="icon-action" id="gcInviteLink" title="Invite link and QR">↗</button>'+(canDelete?'<button class="icon-action danger-icon" id="deleteGc" title="Delete group">🗑</button>':'<button class="icon-action" id="leaveGc" title="Leave group">⇥</button>')+'</div></header><div class="messenger-room-body"><div class="messenger-members-strip" id="gcMembers">Loading members…</div><div id="gcMessages" class="messenger-thread">Loading messages…</div></div><form id="gcSend" class="messenger-composer"><button type="button" class="composer-plus" id="inviteComposer" title="Add people">＋</button><input id="gcText" maxlength="5000" placeholder="Message…" required><button class="send-message" aria-label="Send">➤</button></form>';const m=await supabase.from('chat_members').select('user_id,role,profiles(full_name,school_id)').eq('group_id',id);chatMembers=m.data||[];$('gcMembers').textContent=chatMembers.map(x=>x.profiles?.full_name||'Member').join(' · ');const q=await supabase.from('chat_messages').select('id,sender_id,body,reply_to,created_at,profiles(full_name)').eq('group_id',id).order('created_at',{ascending:true}).limit(100);if(q.error){$('gcMessages').textContent=q.error.message}else{$('gcMessages').innerHTML=(q.data||[]).map(x=>'<div class="messenger-message '+(x.sender_id===user.id?'mine':'')+'">'+(x.sender_id===user.id?'':'<small class="message-author">'+esc(x.profiles?.full_name||'Member')+'</small>')+'<div class="message-bubble">'+chatBody(x.body)+'</div><small class="message-time">'+new Date(x.created_at).toLocaleTimeString([],{hour:'numeric',minute:'2-digit'})+'</small></div>').join('')||'<div class="thread-start"><b>Welcome to '+esc(g.name)+'</b><p>This is the beginning of your group conversation.</p></div>';$('gcMessages').scrollTop=$('gcMessages').scrollHeight}room.querySelector('#gcSend').onsubmit=async e=>{e.preventDefault();const body=$('gcText').value.trim();if(!body)return;const s=await supabase.from('chat_messages').insert({group_id:id,sender_id:user.id,body}).select().single();if(s.error)return toast(s.error.message);$('gcText').value='';const targets=body.includes('@everyone')?chatMembers.filter(x=>x.user_id!==user.id):chatMembers.filter(x=>x.user_id!==user.id&&body.toLowerCase().includes('@'+(x.profiles?.full_name||'').toLowerCase()));for(const t of targets)await supabase.from('chat_notifications').insert({user_id:t.user_id,group_id:id,message_id:s.data.id,kind:'mention'});openChat(id)};room.querySelector('#inviteGc').onclick=()=>inviteDialog(id);room.querySelector('#inviteComposer').onclick=()=>inviteDialog(id);room.querySelector('#gcInviteLink').onclick=()=>{const link=SITE_URL+'?gc='+g.invite_token;const qr='https://api.qrserver.com/v1/create-qr-code/?size=220x220&data='+encodeURIComponent(link);modal('<h2>Invite people</h2><p class="muted">Share this link with an approved CampusOS account.</p><input id="gcLinkValue" readonly value="'+esc(link)+'"><button class="primary wide" id="copyGcLink">Copy invite link</button><div class="qr-preview"><img src="'+qr+'" alt="Group invite QR code"><small>Scan to open the group invite</small></div>');$('copyGcLink').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Invite link copied.')}catch{toast('Select and copy the invite link.')}}};if(canDelete)room.querySelector('#deleteGc').onclick=async()=>{if(!confirm('Permanently delete this group and its messages?'))return;const z=await supabase.rpc('delete_chat_group',{p_group:id});if(z.error)return toast('Delete failed: '+z.error.message);activeChat=null;toast('Group deleted.');await renderChat()};else room.querySelector('#leaveGc').onclick=async()=>{if(!confirm('Leave this group?'))return;const z=await supabase.rpc('leave_chat_group',{p_group:id});if(z.error)return toast(z.error.message);activeChat=null;renderChat()}}
async function inviteDialog(id){const g=chatRows.find(x=>x.id===id);if(!g)return;modal('<h2>Add people to '+esc(g.name)+'</h2><p class="muted">Search approved registered students by name or School ID.</p><div class="messenger-search modal-search">⌕ <input id="gcSearch" placeholder="Search registered student"></div><div id="gcSearchResults" class="invite-results"><p class="muted">Type at least 2 characters.</p></div>');let timer;$('gcSearch').oninput=()=>{clearTimeout(timer);timer=setTimeout(async()=>{const term=$('gcSearch').value.trim();if(term.length<2)return $('gcSearchResults').innerHTML='<p class="muted">Type at least 2 characters.</p>';const r=await supabase.from('profiles').select('id,full_name,school_id,profile_photo_path').eq('status','approved').or('full_name.ilike.%'+term+'%,school_id.ilike.%'+term+'%').limit(20);if(r.error)return $('gcSearchResults').textContent=r.error.message;$('gcSearchResults').innerHTML=(r.data||[]).filter(x=>x.id!==user.id).map(x=>'<div class="invite-person">'+avatar(x.profile_photo_path,x.full_name,'messenger-avatar')+'<div><b>'+esc(x.full_name)+'</b><small>'+esc(x.school_id||'No School ID')+'</small></div><button class="ghost" data-invite="'+x.id+'">Invite</button></div>').join('')||'<p class="muted">No matching approved student.</p>';document.querySelectorAll('[data-invite]').forEach(b=>b.onclick=async()=>{b.disabled=true;const z=await supabase.rpc('invite_chat_member',{p_group:id,p_user:b.dataset.invite});if(z.error){b.disabled=false;return toast(z.error.message)}b.textContent='Invited';toast('Invitation sent.')})},250)}}
