const originalPage=page;window.page=(p)=>{if(p==='chat'){document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));$('page-chat').classList.add('active');document.querySelectorAll('.nav-item[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page==='chat'));$('pageTitle').textContent='Private GCs';renderChat()}else originalPage(p)};


async function openChat(id){activeChat=id;const g=chatRows.find(x=>x.id===id);if(!g)return;const room=$('chatRoom');const isOwner=g.role==='owner',platformAdmin=profile?.role==='admin',canManage=isOwner||g.role==='admin'||platformAdmin,canDelete=isOwner||platformAdmin;room.innerHTML='<div class="messenger-chat-head"><div class="messenger-chat-person">'+avatar(g.photo_path,g.name,'messenger-avatar-lg')+'<div><h3>'+esc(g.name)+'</h3><small class="muted">'+esc(g.role==='owner'?'Owner':g.role==='admin'?'Admin':'Member')+'</small></div></div><div class="gc-tools"><button class="ghost" id="inviteGc">＋ Add people</button><button class="ghost" id="gcInviteLink">🔗 Invite / QR</button>'+(canManage?'<button class="ghost" id="editGc">⚙ Group settings</button>':'')+(canDelete?'<button class="danger-btn" id="deleteGc">Delete GC</button>':'<button class="ghost" id="leaveGc">Leave</button>')+'</div></div><div id="gcMessages" class="messenger-messages">Loading…</div><div id="replyPreview" class="messenger-reply"></div><form id="gcSend" class="messenger-composer"><input id="gcFile" type="file" accept="image/*,.pdf,.txt,.zip,.doc,.docx,.ppt,.pptx,.xls,.xlsx" multiple hidden><button type="button" class="composer-icon" id="attachGc" title="Attach">＋</button><input id="gcText" maxlength="5000" list="gcMentionOptions" placeholder="Message…"><button class="composer-send" title="Send">➤</button></form>';const m=await supabase.from('chat_members').select('user_id,role,profiles(full_name,school_id)').eq('group_id',id);chatMembers=m.data||[];const mentionList=document.createElement('datalist');mentionList.id='gcMentionOptions';mentionList.innerHTML=chatMembers.map(x=>'<option value="@'+esc(x.profiles?.full_name||'')+'"><option value="@'+esc(x.profiles?.school_id||'')+'">').join('');$('gcText').after(mentionList);const q=await supabase.from('chat_messages').select('id,sender_id,body,reply_to,created_at,edited_at,profiles(full_name),chat_attachments(id,storage_path,filename,mime_type)').eq('group_id',id).order('created_at',{ascending:true}).limit(100);if(q.error){$('gcMessages').textContent=q.error.message}else{for(const msg of(q.data||[]))for(const f of(msg.chat_attachments||[])){const signed=await supabase.storage.from('campus-gc').createSignedUrl(f.storage_path,3600);f.signedUrl=signed.data?.signedUrl||null}$('gcMessages').innerHTML=(q.data||[]).map(x=>{const mine=x.sender_id===user.id;const att=(x.chat_attachments||[]).map(f=>f.signedUrl&&/^image\//.test(f.mime_type)?'<a target="_blank" rel="noopener" href="'+esc(f.signedUrl)+'"><img class="gc-attachment-image" alt="'+esc(f.filename)+'" src="'+esc(f.signedUrl)+'"></a>':'<div class="message-file">📎 '+(f.signedUrl?'<a target="_blank" rel="noopener" href="'+esc(f.signedUrl)+'">'+esc(f.filename)+'</a>':esc(f.filename))+'</div>').join('');return '<div class="messenger-row '+(mine?'mine':'')+'" data-message="'+x.id+'"><div class="messenger-bubble">'+(!mine?'<b class="message-name">'+esc(x.profiles?.full_name||'Member')+'</b>':'')+'<div class="message-text">'+chatBody(x.body)+'</div>'+att+'<small>'+new Date(x.created_at).toLocaleTimeString([], {hour:'numeric',minute:'2-digit'})+(x.edited_at?' · edited':'')+'</small></div></div>'}).join('')||'<div class="empty">No messages yet. Say hello 👋</div>';$('gcMessages').scrollTop=$('gcMessages').scrollHeight}$('attachGc').onclick=()=>$('gcFile').click();$('leaveGc')?.addEventListener('click',async()=>{if(!confirm('Leave this group?'))return;const z=await supabase.rpc('leave_chat_group',{p_group:id});if(z.error)return toast(z.error.message);activeChat=null;renderChat()});$('deleteGc')?.addEventListener('click',async()=>{if(!confirm('Delete this GC permanently? All messages, members and invites will be removed.'))return;const z=await supabase.rpc('delete_chat_group',{p_group:id});if(z.error)return toast(z.error.message);activeChat=null;toast('GC deleted.');renderChat()});$('editGc')?.addEventListener('click',async()=>{modal('<h2>Group settings</h2><label>Group name<input id="editGcName" maxlength="80" value="'+esc(g.name)+'"></label><label>Group photo<input id="editGcPhoto" type="file" accept="image/png,image/jpeg,image/webp"></label><button class="primary wide" id="saveGcName">Save details</button><h3>Co-admins</h3><div id="gcAdminCandidates"></div>');$('saveGcName').onclick=async()=>{let photoPath=null;const pic=$('editGcPhoto').files[0];if(pic){if(pic.size>2*1024*1024)return toast('Group photo must be 2 MB or smaller.');const path=id+'/'+user.id+'/group-photo-'+Date.now()+'-'+pic.name;const up=await supabase.storage.from('campus-gc').upload(path,pic,{contentType:pic.type,upsert:true});if(up.error)return toast(up.error.message);photoPath=path}const z=await supabase.rpc('set_chat_group',{p_group:id,p_name:$('editGcName').value.trim(),p_photo_path:photoPath});if(z.error)return toast(z.error.message);closeModal();renderChat()};$('gcAdminCandidates').innerHTML=chatMembers.filter(x=>x.role==='member').map(x=>'<button class="gc-row" data-promote="'+x.user_id+'">'+esc(x.profiles?.full_name||'Member')+' · Make co-admin</button>').join('')||'<p class="muted">No eligible members.</p>';document.querySelectorAll('[data-promote]').forEach(b=>b.onclick=async()=>{if(!isOwner)return toast('Only the owner can appoint co-admins.');const z=await supabase.rpc('promote_chat_admin',{p_group:id,p_user:b.dataset.promote});if(z.error)return toast(z.error.message);toast('Co-admin appointed.');closeModal();openChat(id)})});$('gcSend').onsubmit=async e=>{e.preventDefault();const body=$('gcText').value.trim(),files=[...$('gcFile').files];if(!body&&!files.length)return;const ss=await supabase.from('chat_messages').insert({group_id:id,sender_id:user.id,body:body||' '}).select().single();if(ss.error)return toast(ss.error.message);for(const file of files){if(file.size>20*1024*1024)return toast('Each file must be 20 MB or smaller.');const path=id+'/'+user.id+'/'+crypto.randomUUID()+'-'+file.name;const up=await supabase.storage.from('campus-gc').upload(path,file,{contentType:file.type,upsert:false});if(up.error){toast(up.error.message);continue}const meta=await supabase.from('chat_attachments').insert({message_id:ss.data.id,group_id:id,storage_path:path,filename:file.name,mime_type:file.type||'application/octet-stream',size_bytes:file.size});if(meta.error)toast(meta.error.message)}const targets=/@everyone\b/i.test(body)?chatMembers.filter(x=>x.user_id!==user.id):chatMembers.filter(x=>x.user_id!==user.id&&((x.profiles?.full_name&&body.toLowerCase().includes('@'+x.profiles.full_name.toLowerCase()))||(x.profiles?.school_id&&body.toLowerCase().includes('@'+x.profiles.school_id.toLowerCase()))));for(const t of[...new Map(targets.map(x=>[x.user_id,x])).values()])await supabase.rpc('notify_chat_mention',{p_group:id,p_message:ss.data.id,p_target:t.user_id});$('gcText').value='';$('gcFile').value='';openChat(id)};$('inviteGc').onclick=()=>inviteDialog(id);$('gcInviteLink').onclick=()=>{const link=SITE_URL+'?gc='+g.invite_token;modal('<h2>Invite to '+esc(g.name)+'</h2><p class="muted">Share this link or scan the QR code. The recipient must sign in to an approved CampusOS account.</p><label>Invite link<input id="gcLinkValue" readonly value="'+esc(link)+'"></label><div class="invite-actions"><button class="primary" id="copyGcLink">Copy link</button><a class="ghost" target="_blank" rel="noopener" href="https://api.qrserver.com/v1/create-qr-code/?size=300x300&data='+encodeURIComponent(link)+'">Open QR</a></div><div class="qr-preview"><img alt="Group invite QR code" src="https://api.qrserver.com/v1/create-qr-code/?size=240x240&data='+encodeURIComponent(link)+'"></div>');$('copyGcLink').onclick=async()=>{try{await navigator.clipboard.writeText(link);toast('Invite link copied.')}catch{toast('Copy failed. Select the link manually.')}}}}